App.register({group:'governance',label:'02 / 企业治理',routes:[{path:'governance/tenants',title:'租户空间',icon:'▦',permission:'governance',render(){const rows=DB.tenants.map(t=>`<tr><td><div class="entity"><div class="entity-mark">${t.name.slice(0,1)}</div><div><div class="entity-name">${t.name}</div><div class="entity-meta mono">${t.code}</div></div></div></td><td>${t.owner}</td><td>${t.members}</td><td>${t.projects}</td><td><div style="width:110px">${UI.progress(t.budget?Math.round(t.used/t.budget*100):0,'预算使用')}</div></td><td>${UI.tag(t.status,t.status==='运行中'?'green':'')}</td><td><button class="btn btn-sm" data-action="go:governance/tenant-detail">查看空间</button></td></tr>`);return UI.page('ENTERPRISE / GOVERNANCE','内部租户空间','按事业部、部门、制作中心或业务单元建立隔离工作空间。',UI.btn('＋ 新建租户','tenant:new','btn-primary'),`<div class="notice">企业主体只有一个。租户是企业内部的数据与权限边界，不代表独立法人或独立 SaaS 客户。停用与归档不得删除历史项目。</div><div class="grid grid-3 section-gap">${UI.metric('内部租户',DB.tenants.length,'含归档空间','▦')}${UI.metric('在用成员',DB.users.filter(u=>u.status==='正常').length,'跨租户成员关系按授权建立','♙')}${UI.metric('租户项目',DB.projects.length,'按当前业务归属统计','▣')}</div><div class="card section-gap"><div class="toolbar"><div class="toolbar-left"><b class="small">租户目录</b><span class="tiny muted">默认严格隔离</span></div><div class="toolbar-right"><input class="search" data-filter placeholder="搜索租户名称 / 编码"></div></div>${UI.table(['租户空间','负责人','成员','项目','预算','状态','操作'],rows)}</div>`); }},{path:'governance/tenant-detail',title:'租户详情',icon:'◧',permission:'governance',render(){const t=DB.tenants.find(x=>x.id===DB.state.tenant);return UI.page('ENTERPRISE / TENANT PROFILE','租户治理档案','租户配置、成员关系、资源配额与审计边界。',UI.btn('调整租户策略','tenant:new','btn'),`<div class="grid grid-3"><div class="card"><div class="eyebrow">CURRENT TENANT</div><h2 style="margin:7px 0">${t.name}</h2><div class="mono tiny muted">${t.code}</div>${UI.tag(t.status,'green')}</div>${UI.metric('成员关系',t.members,'当前租户授权成员','♙')}${UI.metric('项目归属',t.projects,'含历史项目','▣')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-title">租户资源与预算策略</div><div class="kpi-line"><span>预算上限</span><b>¥${t.budget.toLocaleString()}</b></div><div class="kpi-line"><span>已消耗</span><b>¥${t.used.toLocaleString()}</b></div><div class="kpi-line"><span>预算使用率</span><b>${t.budget?Math.round(t.used/t.budget*100):0}%</b></div><div class="kpi-line"><span>模型策略</span><b>继承企业白名单</b></div><div class="kpi-line"><span>数据隔离</span>${UI.tag('已启用','green')}</div></div><div class="card"><div class="card-title">租户边界检查</div><div class="timeline section-gap"><div class="timeline-item"><i class="timeline-dot done"></i><div><div class="timeline-title">项目与任务强制绑定 tenantId</div><div class="timeline-meta">项目、生产任务、成本与交付记录</div></div></div><div class="timeline-item"><i class="timeline-dot done"></i><div><div class="timeline-title">成员关系决定访问范围</div><div class="timeline-meta">账号本身不代表全租户访问权</div></div></div><div class="timeline-item"><i class="timeline-dot done"></i><div><div class="timeline-title">跨租户访问留痕</div><div class="timeline-meta">按职责授权，记录范围、用途与期限</div></div></div></div></div></div>`); }},{path:'governance/cross-access',title:'跨租户授权',icon:'⇄',permission:'governance',render(){return UI.page('ENTERPRISE / DELEGATED ACCESS','跨租户授权管理','跨租户访问必须明确对象、租户范围、权限类型、用途与有效期限，并支持撤销。', '',`<div class="notice warn">企业级汇总查看权限不自动等于项目内容读取或修改权限。授权按最小范围生效，所有访问均进入审计。</div><div class="card section-gap"><div class="card-title">当前授权关系</div>${UI.table(['授权编号','授权对象','明确租户范围','权限类型','用途','有效期','状态','操作'],DB.crossAuthorizations.map(a=>`<tr><td class="mono">${a.id}</td><td>${a.actor}</td><td>${a.tenantIds.map(id=>DB.tenants.find(t=>t.id===id)?.name||id).join('、')}</td><td>${a.permission}</td><td>${a.purpose}</td><td>${a.expires}</td><td>${UI.tag(a.status,a.status==='有效'?'green':'')}</td><td>${a.status==='有效'?`<button class="btn btn-sm btn-danger" data-action="cross:revoke" data-id="${a.id}">撤销</button>`:'—'}</td></tr>`))}</div><div class="card section-gap"><div class="card-title">授权检查清单</div><div class="grid grid-2 section-gap"><div class="notice">授权对象：指定员工或管理角色，不对整个企业默认开放。</div><div class="notice">租户范围：显式列出租户 ID，不提供默认全租户授权。</div><div class="notice">权限类型：区分汇总查看、项目只读、内容编辑和资源调配。</div><div class="notice">用途与期限：必须填写业务目的、有效期，并支持提前撤销。</div></div></div>`);}}]});
